insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '6578ff72-fcd3-0f38-cdd4-6cd732495008',id,'writing-introduction','Meet Japanese writing','Introduction','Discover why Japanese uses three scripts, and see them together.','[{"title":"Three scripts, different jobs","text":"Japanese adopted Chinese characters (Kanji), then developed Kana to represent Japanese sounds. Modern writing combines them: Kanji often carries a word''s core meaning, while Hiragana supplies many endings and particles. Katakana often signals borrowed words. You will also see Latin letters and numbers."},{"title":"Read one sentence together","text":"Tap the colored parts below to discover their script. This sentence uses all three systems.","japanese":"私はコーヒーを飲みます。","reading":"Watashi wa kōhī o nomimasu.","translation":"I drink coffee.","segments":[{"text":"私","system":"kanji"},{"text":"は","system":"hiragana"},{"text":"コーヒー","system":"katakana"},{"text":"を","system":"hiragana"},{"text":"飲","system":"kanji"},{"text":"みます","system":"hiragana"}]},{"title":"Two writing directions","text":"Horizontal Japanese runs left to right, with lines going down. Traditional vertical text runs top to bottom, with columns progressing from right to left. Books, signs, and digital screens may use different layouts.","japanese":"あいうえお"},{"title":"The ending matters","text":"A Japanese predicate commonly comes at the end. In the coffee example, 飲みます (drink) finishes the sentence. Subjects and topics can be omitted when the context makes them clear."},{"title":"Sound is not meaning","text":"The Kana あ represents the sound a; it does not normally mean a separate English word. Kanji such as 山 (mountain) carries meaning and can have different readings in different words."}]'::jsonb,0,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '41b0be56-b79e-de10-ab02-c6df8101f98b','6578ff72-fcd3-0f38-cdd4-6cd732495008',null,'coffee-script','choice','{"slug":"coffee-script","kind":"choice","prompt":"Which script writes コーヒー (coffee)?","choices":["Hiragana","Katakana","Kanji"],"answer":"Katakana","explanation":"コーヒー is a borrowed word written in Katakana."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='6578ff72-fcd3-0f38-cdd4-6cd732495008') on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '28bc5331-687a-8249-0407-b4735f851c1a','6578ff72-fcd3-0f38-cdd4-6cd732495008',null,'kana-sound','choice','{"slug":"kana-sound","kind":"choice","prompt":"What does a Kana character normally represent?","choices":["A sound","Always a whole English meaning","Always a full sentence"],"answer":"A sound","explanation":"Kana represent sounds. A written word may combine several Kana."}'::jsonb,1,true where exists(select 1 from public.writing_studio_lessons where id='6578ff72-fcd3-0f38-cdd4-6cd732495008') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '596df316-6c8e-5355-2003-f8df1b0a7bdf',id,'three-writing-systems','Hiragana, Katakana, and Kanji','Writing systems','Learn when to use each script.','[{"title":"Hiragana: ひらがな","text":"Use Hiragana for particles such as は and を, grammatical endings, and many Japanese words. Beginners can write words in Hiragana before learning their Kanji.","japanese":"ねこ","reading":"neko","translation":"cat"},{"title":"Katakana: カタカナ","text":"Katakana represents the same core sounds as Hiragana. It is often used for loanwords, foreign names, emphasis, and some sound effects.","japanese":"カメラ","reading":"kamera","translation":"camera"},{"title":"Kanji: 漢字","text":"Kanji carries meaning, but its reading depends on context. Learn the reading of a word rather than assuming one sound works everywhere.","japanese":"山","reading":"yama (in this word)","translation":"mountain"}]'::jsonb,1,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '165debb6-efcc-98c5-121e-878e520390cf','596df316-6c8e-5355-2003-f8df1b0a7bdf',null,'hiragana','choice','{"slug":"hiragana","kind":"choice","prompt":"Which word is written entirely in Hiragana?","choices":["ねこ","カメラ","山"],"answer":"ねこ","explanation":"ねこ uses Hiragana, カメラ uses Katakana, and 山 is Kanji."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='596df316-6c8e-5355-2003-f8df1b0a7bdf') on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'c46e0e65-734a-f119-03cf-1bb815ba919c','596df316-6c8e-5355-2003-f8df1b0a7bdf',null,'kanji-reading','choice','{"slug":"kanji-reading","kind":"choice","prompt":"How should you learn a Kanji reading?","choices":["In a word and context","Assume every Kanji has one reading"],"answer":"In a word and context","explanation":"For example, 日 is read differently in 日本 and 日曜日."}'::jsonb,1,true where exists(select 1 from public.writing_studio_lessons where id='596df316-6c8e-5355-2003-f8df1b0a7bdf') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '32233ae5-7e01-67a6-21c5-bafcb335ce51',id,'hiragana-a','Your first Hiragana: あ','Characters and handwriting','Hear a, watch its three strokes, trace, then write without a guide.','[{"title":"Meet あ","text":"あ is Hiragana. Its romanization is a, with a vowel sound similar to the a in father. It represents a sound rather than an independent English meaning.","japanese":"あ","reading":"a"},{"title":"Use it in a word","text":"In あさ, combine あ (a) and さ (sa) to read asa. The word means morning.","japanese":"あさ","reading":"asa","translation":"morning"},{"title":"Use it in a sentence","text":"This is a polite statement with です at the end. You will learn this pattern in the grammar lessons.","japanese":"あさです。","reading":"Asa desu.","translation":"It is morning."}]'::jsonb,2,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '1418bc37-0e87-bacf-b28e-7fec6be94b85','32233ae5-7e01-67a6-21c5-bafcb335ce51',null,'read-a','choice','{"slug":"read-a","kind":"choice","prompt":"Choose the reading of あ.","choices":["a","i","u","e"],"answer":"a","explanation":"あ is read a. Its stroke order has three strokes."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='32233ae5-7e01-67a6-21c5-bafcb335ce51') on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'd25fb237-394f-7101-7419-81a4b1e9d75f','32233ae5-7e01-67a6-21c5-bafcb335ce51',(select c.id from public.writing_characters c join public.writing_systems s on s.id=c.writing_system_id join public.languages l on l.id=s.language_id where c.slug='3042' and s.slug='hiragana' and l.code='ja' limit 1),'write-a','character','{"slug":"write-a","kind":"character","prompt":"Trace あ, then write it independently.","answer":"あ","explanation":"Follow the verified three-stroke demonstration. Your drawing is self-reported practice, not an automated handwriting score.","characterSlug":"3042"}'::jsonb,1,true where exists(select 1 from public.writing_studio_lessons where id='32233ae5-7e01-67a6-21c5-bafcb335ce51') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select 'c1f4663f-522d-a51c-7a4b-20fb010ecd3e',id,'word-formation','Build your first words','Word formation','Combine Kana sounds, and notice small characters and long vowels.','[{"title":"Sounds become words","text":"Combine あ + さ to form あさ (morning). The sound of an individual Kana and the meaning of the completed word are different concepts.","japanese":"あさ","reading":"asa","translation":"morning"},{"title":"Small characters change the sound","text":"A small ゃ, ゅ, or ょ combines with the previous character: き + ゃ becomes きゃ (kya), not ki-ya. Small っ creates a short hold before the following consonant.","japanese":"きって","reading":"kitte","translation":"postage stamp"},{"title":"Keep long vowels long","text":"The mark ー lengthens the previous vowel in many Katakana words. コーヒー has a long o and a long i.","japanese":"コーヒー","reading":"kōhī","translation":"coffee"}]'::jsonb,3,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '88f7ecd7-7e98-fed4-eb27-f592449382db','c1f4663f-522d-a51c-7a4b-20fb010ecd3e',null,'morning','word','{"slug":"morning","kind":"word","prompt":"Arrange the Kana to write morning (asa).","tiles":["さ","あ"],"answer":"あさ","reading":"asa","explanation":"あ (a) + さ (sa) makes あさ, morning."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='c1f4663f-522d-a51c-7a4b-20fb010ecd3e') on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'b39c2bed-46dc-6f16-53d0-2e63edb9b8a6','c1f4663f-522d-a51c-7a4b-20fb010ecd3e',null,'cat','word','{"slug":"cat","kind":"word","prompt":"Arrange the Kana to write cat (neko).","tiles":["こ","ね"],"answer":"ねこ","reading":"neko","explanation":"ね (ne) + こ (ko) makes ねこ, cat."}'::jsonb,1,true where exists(select 1 from public.writing_studio_lessons where id='c1f4663f-522d-a51c-7a4b-20fb010ecd3e') on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '8b245c03-cfec-7c86-fc8a-f1723762acda','c1f4663f-522d-a51c-7a4b-20fb010ecd3e',null,'small-tsu','choice','{"slug":"small-tsu","kind":"choice","prompt":"What does small っ do in きって?","choices":["Adds a short hold before t","Makes a long i","Means morning"],"answer":"Adds a short hold before t","explanation":"きって is kitte. The small っ doubles the following consonant."}'::jsonb,2,true where exists(select 1 from public.writing_studio_lessons where id='c1f4663f-522d-a51c-7a4b-20fb010ecd3e') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select 'cad71932-53fb-e721-14ca-6952df2c4ba6',id,'polite-statements','Make a statement with です','Basic grammar','Write a short, polite identification sentence.','[{"title":"Noun + です","text":"です makes a noun statement polite. ねこです can mean It is a cat when the topic is clear. It is not a direct translation for every use of the English verb to be.","japanese":"ねこです。","reading":"Neko desu.","translation":"It is a cat."}]'::jsonb,4,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'f25d3872-15e5-65fe-c923-8032c6c72ec6','cad71932-53fb-e721-14ca-6952df2c4ba6',null,'cat-statement','sentence','{"slug":"cat-statement","kind":"sentence","prompt":"Write: It is a cat.","tiles":["です","ねこ"],"answer":"ねこです。","alternatives":["猫です。"],"reading":"Neko desu.","hint":"cat (ねこ) + です","ending":"です","explanation":"Put the noun first and finish with です. The understood topic need not be written."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='cad71932-53fb-e721-14ca-6952df2c4ba6') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '92eda5c8-6286-5d7c-74cc-2bda3c415506',id,'topic-wa','Introduce a topic with は','Basic grammar','Tell someone what you are talking about.','[{"title":"Topic + は + comment","text":"は marks the topic: as for this. In this role it is pronounced wa, even though the ordinary Hiragana reading is ha. 私は学生です means As for me, I am a student.","japanese":"私は学生です。","reading":"Watashi wa gakusei desu.","translation":"I am a student."}]'::jsonb,5,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '863a1990-4006-54e9-03f1-48e54ab07364','92eda5c8-6286-5d7c-74cc-2bda3c415506',null,'student','sentence','{"slug":"student","kind":"sentence","prompt":"Write: I am a student. Include 私 (I) as the topic.","tiles":["学生","です","は","私"],"answer":"私は学生です。","alternatives":["わたしはがくせいです。","私はがくせいです。","わたしは学生です。"],"requiredParticle":"は","ending":"です","reading":"Watashi wa gakusei desu.","hint":"私 + は + 学生 + です","explanation":"は follows the topic 私. 学生 is the description, and です finishes the polite statement."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='92eda5c8-6286-5d7c-74cc-2bda3c415506') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select 'eb6281f2-3a30-4cf1-0896-93390d7960e7',id,'questions-ka','Ask a question with か','Sentence construction','Turn a polite statement into a question.','[{"title":"Add か at the end","text":"For this polite pattern, add か after です. Japanese does not need to reverse the noun and verb to form this question. A question mark may be used, but か already marks the question.","japanese":"学生ですか。","reading":"Gakusei desu ka.","translation":"Are you a student?"}]'::jsonb,6,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'f33a2079-e203-93be-f60e-a6ebbe8cdf43','eb6281f2-3a30-4cf1-0896-93390d7960e7',null,'student-question','sentence','{"slug":"student-question","kind":"sentence","prompt":"Ask: Are you a student? Use the short form with no explicit topic.","tiles":["か","です","学生"],"answer":"学生ですか。","alternatives":["がくせいですか。"],"requiredParticle":"か","ending":"ですか","reading":"Gakusei desu ka.","hint":"学生 + です + か","explanation":"学生です is a statement. Adding か after です makes it a question."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='eb6281f2-3a30-4cf1-0896-93390d7960e7') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select 'e86f9759-16f4-a230-bf6f-0835096808f3',id,'likes','Say what you like','Sentence construction','Use が好きです to talk about a preference.','[{"title":"Thing + が + 好きです","text":"好き is an adjective-like expression for being fond of something. In this pattern, が marks the thing liked. It is not an action verb taking を.","japanese":"ねこが好きです。","reading":"Neko ga suki desu.","translation":"I like cats."}]'::jsonb,7,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'c11bddbf-3990-cd0a-9f1f-b3db55afbb9c','e86f9759-16f4-a230-bf6f-0835096808f3',null,'like-cats','sentence','{"slug":"like-cats","kind":"sentence","prompt":"Write: I like cats. Leave the topic understood.","tiles":["好き","が","です","ねこ"],"answer":"ねこが好きです。","alternatives":["猫が好きです。","ねこがすきです。","猫がすきです。"],"requiredParticle":"が","ending":"です","reading":"Neko ga suki desu.","hint":"ねこ + が + 好き + です","explanation":"が marks ねこ in this preference pattern. 好きです completes the polite sentence."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='e86f9759-16f4-a230-bf6f-0835096808f3') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '3fd128d4-9d47-8e48-9611-32ff73b87065',id,'dislikes','Say what you do not like','Sentence construction','Use a gentle negative preference.','[{"title":"好きではありません","text":"好きではありません is a polite negative of 好きです: do not like. 好きじゃありません is also a common polite conversational form. 嫌いです expresses dislike more directly.","japanese":"コーヒーが好きではありません。","reading":"Kōhī ga suki dewa arimasen.","translation":"I do not like coffee."}]'::jsonb,8,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '1ef56a22-7886-5815-5137-4d98971f2331','3fd128d4-9d47-8e48-9611-32ff73b87065',null,'not-coffee','sentence','{"slug":"not-coffee","kind":"sentence","prompt":"Write politely: I do not like coffee. Leave the topic understood.","tiles":["ではありません","コーヒー","好き","が"],"answer":"コーヒーが好きではありません。","alternatives":["コーヒーがすきではありません。","コーヒーが好きじゃありません。","コーヒーがすきじゃありません。","コーヒーが嫌いです。","コーヒーがきらいです。"],"requiredParticle":"が","reading":"Kōhī ga suki dewa arimasen.","hint":"コーヒー + が + 好き + ではありません","explanation":"が marks the preference''s object. 好きではありません is a polite negative; 好きじゃありません is conversational. 嫌いです is a stronger statement of dislike."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='3fd128d4-9d47-8e48-9611-32ff73b87065') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '077c192f-3685-a53d-82d6-fba15b1a01b0',id,'objects-and-verbs','Objects and verb endings','Sentence construction','Use を and place the action at the end.','[{"title":"Object + を + verb","text":"を marks a direct object and is normally pronounced o. In 水を飲みます, 水 is what is drunk. The verb 飲みます comes after the object. The understood I is omitted here.","japanese":"水を飲みます。","reading":"Mizu o nomimasu.","translation":"I drink water."}]'::jsonb,9,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '476613ca-228d-001b-1203-9c54b85943b3','077c192f-3685-a53d-82d6-fba15b1a01b0',null,'drink-water','sentence','{"slug":"drink-water","kind":"sentence","prompt":"Write: I drink water. Leave the topic understood.","tiles":["飲みます","水","を"],"answer":"水を飲みます。","alternatives":["みずをのみます。","水をのみます。","みずを飲みます。"],"requiredParticle":"を","ending":"ます","reading":"Mizu o nomimasu.","hint":"水 + を + 飲みます","explanation":"を follows the thing being drunk, 水. Finish with the verb 飲みます. Do not use the topic particle は in place of を for this target pattern."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='077c192f-3685-a53d-82d6-fba15b1a01b0') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '6dad0429-ea97-59ae-22f5-3915d1fc0f04',id,'everyday-sentences','Write an everyday sentence','Independent writing','Combine a topic, an object, and an action.','[{"title":"Put your pieces together","text":"私 is the topic, は marks it, 本 is the direct object, を marks it, and 読みます is the final action. Spaces in the guide are just for learning; ordinary Japanese usually does not put spaces between words.","japanese":"私は本を読みます。","reading":"Watashi wa hon o yomimasu.","translation":"I read a book."}]'::jsonb,10,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '93fe7f03-d9a6-d4b5-3313-0c472715908c','6dad0429-ea97-59ae-22f5-3915d1fc0f04',null,'read-book','sentence','{"slug":"read-book","kind":"sentence","prompt":"Write: I read a book. Include 私 as the topic.","tiles":["本","読みます","は","を","私"],"answer":"私は本を読みます。","alternatives":["わたしはほんをよみます。","私はほんを読みます。","私は本をよみます。","わたしは本を読みます。"],"requiredParticle":"を","ending":"ます","reading":"Watashi wa hon o yomimasu.","hint":"私 + は + 本 + を + 読みます","explanation":"The topic 私は comes first in this model. 本を identifies what is read, and 読みます closes the sentence."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='6dad0429-ea97-59ae-22f5-3915d1fc0f04') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) select '48fcd48a-3448-3e40-44d9-a544c7adf3e3',id,'writing-review','Review your writing toolkit','Review and mastery','Review scripts, pronunciation, grammar, and sentence writing.','[{"title":"A useful beginning","text":"You have met Kana sounds, meaningful Kanji, stroke order, and a few sentence patterns. Keep using the full character grid for daily practice. Workbook completion records practice and recall, not verified handwriting accuracy or full Japanese proficiency."}]'::jsonb,11,true from public.languages where code='ja' on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select '8f1900a2-6351-5e8d-bce0-1a8855732a2c','48fcd48a-3448-3e40-44d9-a544c7adf3e3',null,'wa-reading','choice','{"slug":"wa-reading","kind":"choice","prompt":"How is は pronounced when it marks the topic?","choices":["wa","ha","o"],"answer":"wa","explanation":"The topic particle は is pronounced wa. In many words it is ha."}'::jsonb,0,true where exists(select 1 from public.writing_studio_lessons where id='48fcd48a-3448-3e40-44d9-a544c7adf3e3') on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'a5ef9d52-fe26-9f17-0621-2950d8fde729','48fcd48a-3448-3e40-44d9-a544c7adf3e3',null,'verb-position','choice','{"slug":"verb-position","kind":"choice","prompt":"Where does the verb go in 水を飲みます?","choices":["At the end","Before 水","It is not needed"],"answer":"At the end","explanation":"飲みます is the action and comes after the direct object 水を."}'::jsonb,1,true where exists(select 1 from public.writing_studio_lessons where id='48fcd48a-3448-3e40-44d9-a544c7adf3e3') on conflict do nothing;
insert into public.writing_studio_activities(id,lesson_id,character_id,slug,kind,definition,display_order,is_published) select 'abf8769d-8c9c-9853-0dd1-8aec530ef9d8','48fcd48a-3448-3e40-44d9-a544c7adf3e3',null,'review-tea','sentence','{"slug":"review-tea","kind":"sentence","prompt":"Write: I drink tea. Leave the topic understood.","tiles":["飲みます","お茶","を"],"answer":"お茶を飲みます。","alternatives":["おちゃをのみます。","お茶をのみます。","おちゃを飲みます。"],"requiredParticle":"を","ending":"ます","reading":"Ocha o nomimasu.","hint":"お茶 + を + 飲みます","explanation":"Use を after お茶, then place 飲みます at the end."}'::jsonb,2,true where exists(select 1 from public.writing_studio_lessons where id='48fcd48a-3448-3e40-44d9-a544c7adf3e3') on conflict do nothing;
